function normalizeDbConversions(db){(db||[]).forEach(f=>{if(!Array.isArray(f.conversions)){f.conversions=[];(f.portions||[]).forEach(p=>{if(p&&p.unit)f.conversions.push({id:uid(),amount:num(p.amount)||1,unit:p.unit,basis_multiplier:1,grams:p.grams||'',source:p.source||f.source||'Reference'});});}f.conversions=f.conversions.map(c=>({id:c.id||uid(),amount:c.amount===''?'':(num(c.amount)||1),unit:c.unit||'',basis_multiplier:c.basis_multiplier===''?'':(num(c.basis_multiplier)||1),grams:c.grams??'',source:c.source||f.source||'Custom'}));const q=String(f.name||'').toLowerCase();(PORTION_DB||[]).filter(r=>String(r.food||'').toLowerCase()===q||(r.aliases||[]).some(a=>String(a).toLowerCase()===q)).forEach(r=>{let cv=f.conversions.find(c=>String(c.unit).toLowerCase()===String(r.unit).toLowerCase());let amount=1,bm=1;if(String(f.basis_unit).toLowerCase()==='g'&&num(f.basis_value)>0){amount=num(f.basis_value)/num(r.g_per_unit);bm=1}else if(String(f.basis_unit).toLowerCase()===String(r.unit).toLowerCase()){amount=num(f.basis_value)||1;bm=1}else return;if(!cv)f.conversions.push({id:uid(),amount:round(amount,3),unit:r.unit,basis_multiplier:bm,grams:round(amount*num(r.g_per_unit),2),source:r.source||'Portion reference'});else if((cv.grams===''||cv.grams==null)&&num(cv.amount)>0)cv.grams=round(num(cv.amount)*num(r.g_per_unit),2);});});return db}
function savedConversions(f){return Array.isArray(f?.conversions)?f.conversions:[]}
const PROTEIN_SOURCE_OPTIONS=[
  ['meat','Meat — count'],
  ['egg','Egg — count'],
  ['milk','Milk — count'],
  ['formula','Formula — count'],
  ['cho_source','CHO source — exclude'],
  ['other','Other — exclude'],
  ['unclassified','Unclassified — review']
];
function inferProteinSource(f){
  const t=String(f?.type||'').toLowerCase(),cat=String(f?.category||'').toLowerCase(),n=String(f?.name||'').toLowerCase();
  if(t==='formula') return 'formula';
  if(cat==='milk') return 'milk';
  if(cat==='meat') return /ไข่|egg/.test(n)?'egg':'meat';
  if(cat==='rice_starch') return 'cho_source';
  if(cat==='fruit') return 'other';
  if(t==='modular') return 'other';
  if(/ไข่|egg/.test(n)) return 'egg';
  if(/นม|milk|โยเกิร์ต|yogurt|ชีส|cheese/.test(n)) return 'milk';
  if(/ไก่|หมู|ปลา|กุ้ง|ปู|หอย|เป็ด|ตับ|แฮม|เบคอน|กุนเชียง|ไส้กรอก|หมูยอ|แหนม|ลูกชิ้น|เนื้อวัว|เนื้อสัตว์|อกไก่|ปีกไก่/.test(n)) return 'meat';
  if(/ข้าว|โจ๊ก|ข้าวต้ม|เส้น|บะหมี่|มักกะโรนี|สปาเกต|วุ้นเส้น|สาคู|ขนมปัง|แครกเกอร์|แป้ง|มันฝรั่ง|มันเทศ|เผือก|ข้าวโพด|ถั่วเมล็ดแห้ง|น้ำตาล|dextrin|sucrose/.test(n)) return 'cho_source';
  return 'unclassified';
}
function migrateProteinSourceCategory(f){
  const ps=String(f?.protein_source||'');
  if(ps==='meat_egg') return /ไข่|egg/i.test(String(f?.name||''))?'egg':'meat';
  if(ps==='milk_formula') return String(f?.type||'').toLowerCase()==='formula'?'formula':'milk';
  return ps||inferProteinSource(f);
}
