function sortMeals(){state.meals.sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));saveState()}function hasPortion(x){return x.weight_g!==''||x.volume_ml!==''||x.amount!==''||x.formulaKcalOz!==''}function portionText(x){if(x.weight_g!=='')return `${x.weight_g} g`;if(x.volume_ml!=='')return `${x.volume_ml} mL`;if(x.original_amount&&x.original_amount!==String(x.amount))return `${x.original_amount}${x.unit?' '+x.unit:''}`;return x.amount!==''?`${x.amount}${x.unit?' '+x.unit:''}`:''}function ingText(i){return `${i.food||'(ไม่ระบุ)'}${portionText(i)?' '+portionText(i):''}`}
