function customDbCandidates(name='',types=['food','formula','modular']){const q=String(name||'').trim().toLowerCase();const rows=state.foodDB.filter(f=>types.includes(f.type));if(!q)return rows.slice(0,40);const clean=x=>String(x||'').toLowerCase().replace(/เนื้อ/g,'').replace(/สุก|ดิบ/g,'').replace(/\s+/g,' ').trim();const tq=clean(q);const score=f=>{const n=String(f.name||'').toLowerCase(),tn=clean(n);if(n===q)return 120;if(tn===tq)return 110;if(n.startsWith(q)||q.startsWith(n))return 100;if(n.includes(q)||q.includes(n))return 90;if(tq&&(tn.includes(tq)||tq.includes(tn)))return 80;let pts=0;for(const t of tq.split(/\s+/).filter(Boolean))if(tn.includes(t))pts+=12;return pts};return rows.map(f=>[f,score(f)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]||String(a[0].name).localeCompare(String(b[0].name),'th')).slice(0,30).map(x=>x[0])}
