function addIntakeAt(time=''){ensureReviewDraft().push(normItem({time,food:'',needs_review:true}));ensureReviewDraft().sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));markReviewDirty();renderMeals()}function addIntakeAfterTime(time,newTime=''){const idxs=ensureReviewDraft().map((m,i)=>m.time===time?i:-1).filter(i=>i>=0),idx=idxs.length?idxs[idxs.length-1]:ensureReviewDraft().length-1;ensureReviewDraft().splice(idx+1,0,normItem({time:newTime,food:'',needs_review:true}));markReviewDirty();renderMeals()}
function renderMeals(){if($('reviewSaveStatus'))$('reviewSaveStatus').innerHTML=reviewDirty?'<span class="dirty-pill">Unsaved changes</span>':'<span class="saved-pill">Saved</span>';const c=$('mealsContainer');c.innerHTML='';const filtered=state.settings.needsReviewOnly?ensureReviewDraft().filter(needsReview):ensureReviewDraft();const groups={};filtered.forEach(m=>(groups[m.time||'No time']??=[]).push(m));const nReview=ensureReviewDraft().filter(needsReview).length;$('reviewSummary').textContent=`${ensureReviewDraft().length} items • ${nReview} need review`;$('needsReviewBtn').textContent=`Needs review only: ${state.settings.needsReviewOnly?'On':'Off'}`;$('reviewWarnings').innerHTML=(state.pnif.warnings||[]).length?`<div class="warning-box">${state.pnif.warnings.map(esc).join(' • ')}</div>`:'';const entries=Object.entries(groups);entries.forEach(([time,items],idx)=>{const card=document.createElement('div');card.className='time-card';card.innerHTML=`<div class="time-head"><span>${esc(time)}</span><div class="inline-actions"><button class="small-btn secondary add-time">+ Add at this time</button><button class="small-btn secondary add-between">+ Add intake between</button></div></div>`;card.querySelector('.add-time').onclick=()=>addIntakeAt(time==='No time'?'':time);card.querySelector('.add-between').onclick=()=>{const next=entries[idx+1]?.[0]||'';const val=prompt(`เวลา intake ใหม่${next?` ระหว่าง ${time}–${next}`:` หลัง ${time}`} (เช่น 08:00)`,'');if(val!==null&&val.trim())addIntakeAfterTime(time==='No time'?'':time,val.trim().replace('.',':'))};items.forEach(m=>card.appendChild(menuNode(m)));c.appendChild(card)});if(!filtered.length)c.innerHTML='<p class="muted">ไม่มีรายการใน filter นี้</p>'}
function menuNode(m){const wrap=document.createElement('div');wrap.className='menu-row';const ing=(m.ingredients||[]).map(ingText);const shown=ing.slice(0,3).join(' • ')+(ing.length>3?` • +${ing.length-3} more`:'');const reasons=menuReviewReasons(m);wrap.innerHTML=`<div class="menu-main"><div><div class="menu-title">${esc(m.food||'(ยังไม่ได้ระบุเมนู)')} <span class="portion">${esc(portionText(m))}</span></div>${shown?`<div class="ingredients-line">ส่วนประกอบ: ${esc(shown)}</div>`:''}<div class="badges">${reasons.length?`<span class="badge warn">Needs review: ${esc(reasons[0])}</span>`:'<span class="badge ok-badge">Ready</span>'}</div></div><div class="menu-actions"><button class="small-btn secondary edit">Edit</button><button class="small-btn secondary insert">Insert below</button><button class="small-btn danger del">Delete</button></div></div><div class="edit-slot"></div>`;wrap.querySelector('.edit').onclick=()=>{m.editOpen=!m.editOpen;renderMeals()};wrap.querySelector('.insert').onclick=()=>{const idx=ensureReviewDraft().findIndex(x=>x.id===m.id);ensureReviewDraft().splice(idx+1,0,normItem({time:m.time,food:'',needs_review:true}));markReviewDirty();renderMeals()};wrap.querySelector('.del').onclick=()=>{const a=ensureReviewDraft(),idx=a.findIndex(x=>x.id===m.id);if(idx>=0)a.splice(idx,1);markReviewDirty();renderMeals()};if(m.editOpen)wrap.querySelector('.edit-slot').appendChild(editPanel(m));return wrap}
function editPanel(m){const d=document.createElement('div');d.className='edit-panel';const cands=customDbCandidates(m.food),units=unitsForIngredient(m),mf=matchedFood(m),isFormula=mf?.type==='formula',powderG=formulaPowderGrams(m,mf);d.innerHTML=`<div class="edit-grid"><label>Time<input data-k="time" value="${esc(m.time)}"></label><label>Intake type<select data-k="intake_type"><option value="food" ${m.intake_type==='food'?'selected':''}>Food</option><option value="formula" ${m.intake_type==='formula'?'selected':''}>Formula</option><option value="unknown" ${m.intake_type==='unknown'?'selected':''}>Unknown / review</option></select></label><label>Reported menu<input data-k="food" value="${esc(m.food)}"></label><label>Food / Formula / Modular match<select data-k="dbMatchId"><option value="">— choose closest —</option>${cands.map(x=>`<option value="${x.id}" ${m.dbMatchId===x.id?'selected':''}>[${esc(x.type)}] ${esc(x.name)}</option>`).join('')}</select></label><label>Amount<input data-k="amount" value="${esc(m.original_amount||m.amount)}"></label><label>Unit<select data-k="convertUnit"><option value="">— choose unit —</option>${units.map(u=>`<option value="${esc(u)}" ${(m.convertUnit||m.unit)===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><label>Weight g<input data-k="weight_g" type="number" step="0.1" value="${esc(m.weight_g)}"></label><label>Volume mL<input data-k="volume_ml" type="number" step="0.1" value="${esc(m.volume_ml)}"></label>${isFormula?`<label>Formula concentration (kcal/oz)<input data-k="formulaKcalOz" type="number" step="0.1" value="${esc(m.formulaKcalOz||'')}" placeholder="เช่น 20, 24, 30"></label>`:''}</div><div class="calc-note">${mf?`Matched: [${esc(mf.type)}] ${esc(mf.name)} • basis ${esc(mf.basis_value)} ${esc(mf.basis_unit)}`:'เลือก DB match และ unit ที่รองรับเพื่อคำนวณ'}${isFormula&&String(mf.basis_unit||'').toLowerCase()==='g'?` • Formula: kcal = kcal/oz × volume/30${powderG!==null?` → powder ${round(powderG,2)} g`:''}`:''} • Need review จะหายอัตโนมัติเมื่อคำนวณได้</div><div class="section-title-row top-gap"><strong>Ingredients</strong><button class="small-btn secondary add-ing">+ Ingredient</button></div><div class="ings"></div><label class="top-gap">Note<input data-k="note" value="${esc(m.note)}"></label>`;d.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.k;if(k==='dbMatchId'){m.dbMatchId=el.value;const f=state.foodDB.find(x=>x.id===el.value);if(f){m.convertFood=f.name;m.raw_cooked=defaultFoodState(f.name,m.raw_cooked);m.sourcePreference='Custom';if(f.type==='formula')m.intake_type='formula';else if(m.intake_type!=='unknown')m.intake_type='food'}if(f?.type!=='formula')m.formulaKcalOz=''}else if(k==='amount'){const a=normAmt(el.value);m.amount=a.value;m.original_amount=el.value}else{m[k]=el.value}markReviewDirty();renderMeals()}));const box=d.querySelector('.ings');(m.ingredients||[]).forEach(i=>box.appendChild(ingEditor(m,i)));d.querySelector('.add-ing').onclick=()=>{m.ingredients.push(normIng({}));markReviewDirty();renderMeals()};return d}
function convertToGrams(x){if(x.weight_g!=='')return num(x.weight_g);const cu=x.convertUnit||x.unit;if(String(cu).toLowerCase()==='g')return num(x.amount);const f=matchedFood(x);if(f&&x.amount!==''&&String(cu).toLowerCase()==='scoop'&&num(f.grams_per_scoop)>0)return num(x.amount)*num(f.grams_per_scoop);if(f&&x.amount!==''){const cv=savedConversions(f).find(c=>String(c.unit).toLowerCase()===String(cu).toLowerCase()&&num(c.grams)>0);if(cv)return num(x.amount)/num(cv.amount)*num(cv.grams)}const cf=x.convertFood||f?.name||x.food,q=String(cf||'').toLowerCase();const hit=state.portionDB.find(r=>(r.food.toLowerCase()===q||(r.aliases||[]).some(a=>a.toLowerCase()===q))&&r.unit===cu);return hit&&x.amount!==''?num(x.amount)*num(hit.g_per_unit):null}
function ingEditor(m,i){const f=matchedFood(i),cands=customFoodCandidates(i.food),units=unitsForIngredient(i),g=convertToGrams(i),reason=ingredientReviewReason(i),isFormula=f?.type==='formula',powderG=formulaPowderGrams(i,f);const r=document.createElement('div');r.className=`ingredient-editor ${reason?'needs-review-row':'ready-row'}`;r.innerHTML=`<label>Reported ingredient<input data-k="food" value="${esc(i.food)}"></label><label>Food / Formula / Modular<select data-k="dbMatchId"><option value="">— choose closest —</option>${cands.map(x=>`<option value="${x.id}" ${i.dbMatchId===x.id?'selected':''}>[${esc(x.type)}] ${esc(x.name)}</option>`).join('')}</select></label><label>Amount<input data-k="amount" value="${esc(i.original_amount||i.amount)}"></label><label>Unit<select data-k="convertUnit"><option value="">— choose unit —</option>${units.map(u=>`<option value="${esc(u)}" ${(i.convertUnit||i.unit)===u?'selected':''}>${esc(u)}</option>`).join('')}</select></label><label>Volume mL<input data-k="volume_ml" type="number" step="0.1" value="${esc(i.volume_ml)}"></label>${isFormula?`<label>Formula kcal/oz<input data-k="formulaKcalOz" type="number" step="0.1" value="${esc(i.formulaKcalOz||'')}" placeholder="เช่น 20, 24, 30"></label>`:''}<label>Calculated weight<input disabled value="${powderG!==null?round(powderG,2)+' g formula powder':(g!==null?round(g,1)+' g':(f&&f.basis_unit!=='g'?'Uses '+f.basis_unit:'Needs conversion'))}"></label><div class="ingredient-status">${reason?`<span class="badge warn">⚠ ${esc(reason)}</span>`:'<span class="badge ok-badge">✓ Ready to calculate</span>'}</div><button class="small-btn danger ingredient-delete">Delete</button>`;r.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.k;if(k==='dbMatchId'){i.dbMatchId=el.value;const mf=state.foodDB.find(f=>f.id===el.value);if(mf){i.convertFood=mf.name;i.raw_cooked=defaultFoodState(mf.name,i.raw_cooked)}if(mf?.type!=='formula')i.formulaKcalOz=''}else if(k==='amount'){const a=normAmt(el.value);i.amount=a.value;i.original_amount=el.value}else{i[k]=el.value}markReviewDirty();renderMeals()}));r.querySelector('.ingredient-delete').onclick=()=>{m.ingredients=m.ingredients.filter(x=>x.id!==i.id);markReviewDirty();renderMeals()};return r}
$('addMealBtn').addEventListener('click',()=>{ensureReviewDraft().push(normItem({needs_review:true}));markReviewDirty();renderMeals()});$('needsReviewBtn').addEventListener('click',()=>{state.settings.needsReviewOnly=!state.settings.needsReviewOnly;saveState();renderMeals()});

$('saveReviewBtn').addEventListener('click',()=>{state.meals=clone(ensureReviewDraft());saveState();resetReviewDraft();renderMeals()});$('cancelReviewBtn').addEventListener('click',()=>{resetReviewDraft();renderMeals()});

function exactCustom(name){const q=String(name||'').trim().toLowerCase();return state.foodDB.find(f=>f.name.trim().toLowerCase()===q)||state.foodDB.find(f=>f.name.toLowerCase().includes(q)||q.includes(f.name.toLowerCase()))}
function factorFor(x,f){const bu=String(f.basis_unit||'').toLowerCase(),xu=String(x.convertUnit||x.unit||'').toLowerCase();const fg=formulaPowderGrams(x,f);if(fg!==null&&bu==='g')return fg/num(f.basis_value);const cg=convertToGrams(x);if(cg!==null&&bu==='g')return cg/num(f.basis_value);if(x.volume_ml!==''&&bu==='ml')return num(x.volume_ml)/num(f.basis_value);if(xu===bu&&x.amount!=='')return num(x.amount)/num(f.basis_value);const cv=savedConversions(f).find(c=>String(c.unit).toLowerCase()===xu);if(cv&&x.amount!=='')return num(x.amount)/num(cv.amount)*num(cv.basis_multiplier||1);const hp=(f.portions||[]).find(p=>String(p.unit).toLowerCase()===xu);if(hp&&x.amount!=='')return num(x.amount)/num(hp.amount);return null}
const NUT=['kcal','protein','fat','mct','cho','calcium','magnesium','phosphorus','sodium','potassium','iron','zinc'];const TOTAL_KEYS=[...NUT,'protein_excl_cho'];function emptyNut(){const t=Object.fromEntries(NUT.map(k=>[k,0]));t.protein_excl_cho=0;return t}function addNut(t,f,fac){NUT.forEach(k=>t[k]+=num(f[k])*fac);if(proteinSourceCounts(f))t.protein_excl_cho+=num(f.protein)*fac}

function medicationMineralReady(f){
  if(f?.type!=='medication')return true;
  return ['sodium','potassium','calcium','magnesium','phosphorus'].some(k=>f[k]!==''&&f[k]!==null&&f[k]!==undefined&&Number.isFinite(Number(f[k])));
}
function calcPart(x,time,missing){const f=matchedFood(x);if(!f){missing.push({time,food:x.food,reason:'No Custom Database match'});return null}if(!medicationMineralReady(f)){missing.push({time,food:x.food,reason:'Medication/mineral template: enter product-specific Na/K/Ca/Mg/P in mg first'});return null}const fac=factorFor(x,f);if(fac===null){missing.push({time,food:x.food,reason:`Need ${f.basis_unit} amount or matching unit`});return null}const t=emptyNut();addNut(t,f,fac);return t}
function calculateIntake(){const total=emptyNut(),missing=[];let calcItems=0;const addPart=(x,time)=>{const t=calcPart(x,time,missing);if(!t)return false;TOTAL_KEYS.forEach(k=>total[k]+=t[k]);return true};state.meals.forEach(m=>{let method=m.calcMethod==='auto'?autoCalcRule(m).method:m.calcMethod;let any=false;if(method==='none'){missing.push({time:m.time,food:m.food,reason:'Portion missing'});return}if(method==='whole'){if(addPart(m,m.time))any=true}else if(method==='ingredients'){(m.ingredients||[]).filter(hasPortion).forEach(i=>{if(addPart(i,m.time))any=true});if((m.ingredients||[]).some(i=>!hasPortion(i)))missing.push({time:m.time,food:m.food,reason:'Some ingredients have no portion; calculated reported components only'})}else if(method==='hybrid'){(m.ingredients||[]).filter(hasPortion).forEach(i=>{if(addPart(i,m.time))any=true});missing.push({time:m.time,food:m.food,reason:'Hybrid: only reported quantified ingredients calculated; unreported remainder not estimated automatically'})}if(any)calcItems++});state.lastSummary={total,foodFormulaTotal:clone(total),foodTotal:clone(total),specialTotal:emptyNut(),missing,calcItems,totalItems:state.meals.length,at:new Date().toISOString()};saveState();return state.lastSummary}
function lctKcal(t){return num(t?.fat)*9}
function mctKcal(t){return num(t?.mct)*8.3}
function fatEnergyKcal(t){return lctKcal(t)+mctKcal(t)}
function totalFatGrams(t){return num(t?.fat)+num(t?.mct)}
function fatEnergyPct(t){const total=num(t?.kcal);return total>0?fatEnergyKcal(t)/total*100:0}
function macroRatio(t){
  const kcal=[num(t.protein)*4,num(t.cho)*4,fatEnergyKcal(t)],total=kcal.reduce((a,b)=>a+b,0);
  if(!total)return '—';
  const exact=kcal.map(v=>v*100/total),pct=exact.map(Math.floor),left=100-pct.reduce((a,b)=>a+b,0);
  exact.map((v,i)=>({i,r:v-Math.floor(v)})).sort((a,b)=>b.r-a.r).slice(0,left).forEach(x=>pct[x.i]++);
  return `P ${pct[0]}% : CHO ${pct[1]}% : Fat ${pct[2]}%`;
}
function proteinDisplay(g,w,prefix=''){const bw=w?` <span class="protein-perkg">(${prefix}${round(g/w,2)} g/kg/day)</span>`:' <span class="protein-perkg">(BW required)</span>';return `${prefix}${round(g)} g/day${bw}`}
function nutGrid(t,prefix=''){const w=num(state.patient.weight);return `<div class="summary-grid top-gap"><div class="metric">Energy<b>${prefix}${round(t.kcal)} kcal/day</b></div><div class="metric">Total protein<b>${proteinDisplay(num(t.protein),w,prefix)}</b></div><div class="metric">Protein from meat / egg / milk / formula<b>${proteinDisplay(num(t.protein_excl_cho),w,prefix)}</b><span>Counts only: meat, egg, milk, formula</span></div><div class="metric">P:CHO:Fat<b>${macroRatio(t)}</b><span>% of macronutrient energy; no decimals</span></div><div class="metric">Total fat<b>${prefix}${round(totalFatGrams(t))} g/day</b><span>${prefix}${round(fatEnergyKcal(t),1)} kcal • ${prefix}${round(fatEnergyPct(t),1)}% total energy</span></div><div class="metric">LCT<b>${prefix}${round(t.fat)} g/day</b><span>${prefix}${round(lctKcal(t),1)} kcal</span></div><div class="metric">MCT<b>${prefix}${round(t.mct)} g/day</b><span>${prefix}${round(mctKcal(t),1)} kcal</span></div><div class="metric">CHO<b>${prefix}${round(t.cho)} g/day</b></div><div class="metric">Ca<b>${prefix}${round(t.calcium)} mg</b></div><div class="metric">Mg<b>${prefix}${round(t.magnesium)} mg</b></div><div class="metric">P<b>${prefix}${round(t.phosphorus)} mg</b></div><div class="metric">Na<b>${prefix}${round(t.sodium)} mg</b><span>${prefix}${round(t.sodium/23,2)} mEq</span></div><div class="metric">K<b>${prefix}${round(t.potassium)} mg</b><span>${prefix}${round(t.potassium/39,2)} mEq</span></div><div class="metric">Fe<b>${prefix}${round(t.iron)} mg</b></div><div class="metric">Zn<b>${prefix}${round(t.zinc)} mg</b></div></div>`}

function detailAmountText(x,f,fac){
  const fg=formulaPowderGrams(x,f),basis=`${round(num(f.basis_value),2)} ${f.basis_unit}`;
  if(fg!==null)return `${round(fg,2)} g formula powder (from ${round(num(x.formulaKcalOz),1)} kcal/oz × ${round(num(x.volume_ml),1)} mL) → ${round(fac,4)} × DB basis ${basis}`;
  if(x.weight_g!=='')return `${round(num(x.weight_g),2)} g → ${round(fac,4)} × DB basis ${basis}`;
  if(x.volume_ml!==''&&String(f.basis_unit||'').toLowerCase()==='ml')return `${round(num(x.volume_ml),2)} mL → ${round(fac,4)} × DB basis ${basis}`;
  const amt=x.original_amount||x.amount,unit=x.convertUnit||x.unit||'';
  return `${amt!==''?esc(amt):'—'}${unit?' '+esc(unit):''} → ${round(fac,4)} × DB basis ${esc(basis)}`;
}
function dbReferenceText(f){
  return `[${esc(f.type)}] ${esc(f.name)} • basis ${round(num(f.basis_value),2)} ${esc(f.basis_unit)} • ${round(num(f.kcal),2)} kcal, P ${round(num(f.protein),2)} g, fat ${round(num(f.fat),2)} g, Ca ${round(num(f.calcium),2)} mg, Na ${round(num(f.sodium),2)} mg, K ${round(num(f.potassium),2)} mg`;
}
function detailRowHtml(r){return `<tr><td>${esc(r.context||'—')}</td><td>${esc(r.label||'—')}</td><td>${r.ref||'—'}</td><td>${r.amount||'—'}</td><td>${round(r.n.kcal,2)}</td><td>${round(r.n.protein,2)}</td><td>${round(r.n.fat,2)}</td><td>${round(r.n.calcium,2)}</td><td>${round(r.n.sodium,2)}</td><td>${round(r.n.potassium,2)}</td></tr>`}
function detailFootHtml(label,t){return `<tr class="calc-total-row"><th colspan="4">${esc(label)}</th><th>${round(t.kcal,2)}</th><th>${round(t.protein,2)}</th><th>${round(t.fat,2)}</th><th>${round(t.calcium,2)}</th><th>${round(t.sodium,2)}</th><th>${round(t.potassium,2)}</th></tr>`}
function buildFoodCalculationRows(){
  const rows=[],missing=[];
  state.meals.forEach(m=>{
    const method=m.calcMethod==='auto'?autoCalcRule(m).method:m.calcMethod;
    const add=(x,label)=>{const f=matchedFood(x);if(!f){missing.push(`${m.time||'—'} ${label}: no Custom DB match`);return}const fac=factorFor(x,f);if(fac===null){missing.push(`${m.time||'—'} ${label}: amount/unit cannot be converted to ${f.basis_value} ${f.basis_unit}`);return}const n=emptyNut();addNut(n,f,fac);rows.push({context:`${m.time||'—'} • ${m.food||'(menu)'}`,label,ref:dbReferenceText(f),amount:detailAmountText(x,f,fac),n})};
    if(method==='whole')add(m,m.food||'(menu)');
    else if(method==='ingredients'||method==='hybrid')(m.ingredients||[]).filter(hasPortion).forEach(i=>add(i,i.food||'(ingredient)'));
    else missing.push(`${m.time||'—'} ${m.food||'(menu)'}: no calculable portion`);
  });
  return {rows,missing};
}
function scaledComponentAmountText(c,ratio,f){
  const unit=c.unit||'';const recipe=`${c.amount!==''?c.amount:'—'}${unit?' '+unit:''}`;
  if(!(ratio>0))return '—';
  const scaled=num(c.amount)*ratio;
  if(c.amount!==''&&!Number.isNaN(scaled))return `${round(scaled,3)}${unit?' '+esc(unit):''} (${round(ratio,4)} × recipe amount)`;
  return `${round(ratio,4)} × recipe amount`;
}
function buildModularCalculationRows(){
  const rows=[],missing=[],recipe=modularTotals(),vol=num(state.modular.finalVolume),act=state.modular.feeds.reduce((z,x)=>z+num(x.actual),0),pres=state.modular.feeds.reduce((z,x)=>z+num(x.prescribed),0),used=act||pres,ratio=vol?used/vol:0;
  state.modular.components.forEach(c=>{const f=c.dbMatchId?state.foodDB.find(x=>x.id===c.dbMatchId):exactCustom(c.name);if(!f){missing.push(`${c.name||'(component)'}: no Custom DB match`);return}const recipeN=componentCalc(c);const n=emptyNut();TOTAL_KEYS.forEach(k=>n[k]=recipeN[k]*ratio);rows.push({context:'',label:c.name||f.name,ref:dbReferenceText(f),recipeAmount:`${c.amount!==''?esc(c.amount):'—'}${c.unit?' '+esc(c.unit):''}`,amount:scaledComponentAmountText(c,ratio,f),n})});
  const total=emptyNut();rows.forEach(r=>TOTAL_KEYS.forEach(k=>total[k]+=r.n[k]));
  return {rows,missing,total,vol,act,pres,used,ratio,recipe};
}
function renderCalculationDetail(){
  calculateIntake();
  const food=buildFoodCalculationRows(),foodTotal=emptyNut();food.rows.forEach(r=>TOTAL_KEYS.forEach(k=>foodTotal[k]+=r.n[k]));
  $('foodCalcDetailBody').innerHTML=food.rows.length?food.rows.map(detailRowHtml).join(''):`<tr><td colspan="10" class="muted">ไม่มีรายการจาก Review Intake ที่คำนวณได้</td></tr>`;
  $('foodCalcDetailFoot').innerHTML=detailFootHtml('รวมจาก Food + Formula / Review Intake',foodTotal);
  const mod=buildModularCalculationRows();
  $('modCalcBasisNote').textContent=mod.used&&mod.vol?`Daily intake ใช้ ${mod.act?'actual':'prescribed'} ${round(mod.used,2)} mL จาก final recipe volume ${round(mod.vol,2)} mL → factor ${round(mod.ratio,4)} ของสูตรทั้งหมด`:(mod.rows.length?'ยังไม่มี final volume + actual/prescribed volume ที่เพียงพอ จึงยังไม่เกิด nutrient contribution จาก Daily Modular Diet':'ยังไม่มี Daily Modular Recipe component');
  $('modCalcDetailBody').innerHTML=mod.rows.length?mod.rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${r.ref}</td><td>${r.recipeAmount}</td><td>${r.amount}</td><td>${round(r.n.kcal,2)}</td><td>${round(r.n.protein,2)}</td><td>${round(r.n.fat,2)}</td><td>${round(r.n.calcium,2)}</td><td>${round(r.n.sodium,2)}</td><td>${round(r.n.potassium,2)}</td></tr>`).join(''):`<tr><td colspan="10" class="muted">ไม่มี Modular Diet component</td></tr>`;
  $('modCalcDetailFoot').innerHTML=detailFootHtml('รวมจาก Daily Modular Diet',mod.total);
  const grand=emptyNut();TOTAL_KEYS.forEach(k=>grand[k]=foodTotal[k]+mod.total[k]);
  const warnings=[...food.missing,...mod.missing];
  $('calcDetailWarnings').innerHTML=`<div class="calc-grand-total"><strong>รวม Food + Formula + Daily Modular Diet:</strong> Energy ${round(grand.kcal,2)} kcal • Protein ${round(grand.protein,2)} g • Fat ${round(grand.fat,2)} g • Ca ${round(grand.calcium,2)} mg • Na ${round(grand.sodium,2)} mg • K ${round(grand.potassium,2)} mg</div>${warnings.length?`<div class="warning-box"><strong>รายการที่ยัง manual recheck ไม่ได้เต็มรูปแบบ</strong>${warnings.map(x=>`<div>${esc(x)}</div>`).join('')}</div>`:''}`;
}
function renderSummary(){const s=calculateIntake(),foodFormula=s.foodFormulaTotal||s.total||emptyNut(),incomplete=s.missing.length>0,recipe=modularTotals(),vol=num(state.modular.finalVolume),act=state.modular.feeds.reduce((z,x)=>z+num(x.actual),0),pres=state.modular.feeds.reduce((z,x)=>z+num(x.prescribed),0),used=act||pres,ratio=vol?used/vol:0,modDiet=emptyNut();TOTAL_KEYS.forEach(k=>modDiet[k]=recipe[k]*ratio);const total=emptyNut();TOTAL_KEYS.forEach(k=>total[k]=foodFormula[k]+modDiet[k]);$('nutrientSummary').innerHTML=`${incomplete?`<div class="incomplete">Intake incomplete • ${s.calcItems}/${s.totalItems} Review Intake items contributed</div>`:''}<h3>1. Food + Formula</h3><p class="muted">รวมทุก item ที่คำนวณได้จาก Review Intake รวม formula และ modular-component item ที่ใช้เป็นส่วนของ intake</p>${nutGrid(foodFormula,incomplete?'≥ ':'')}<h3 class="top-gap">2. Modular Diet</h3><p class="muted">เฉพาะ Daily Modular Diet${used?` • ${act?'actual':'prescribed'} ${round(used)} mL/day จาก final volume ${round(vol)} mL`:''}</p>${nutGrid(modDiet)}<h3 class="top-gap">3. Total daily intake</h3>${nutGrid(total,incomplete?'≥ ':'')}${requirementCompare(total)}`;$('unmatchedList').innerHTML=s.missing.length?`<div class="unmatched"><strong>Not calculated / partial (${s.missing.length})</strong>${s.missing.map(x=>`<div>${esc(x.time||'—')} — ${esc(x.food||'(blank)')}: ${esc(x.reason)}</div>`).join('')}</div>`:'<div class="status ok">All calculable Review Intake items were calculated from Custom Database.</div>'}
function requirementCompare(t){const r=state.requirements,w=num(state.patient.weight),a=[];if(r.trackFluid&&r.fluid)a.push(`Fluid target ${esc(r.fluid)} mL/day`);if(r.energy)a.push(`Energy ${round(t.kcal/num(r.energy)*100,1)}% target`);if(r.protein)a.push(`Protein ${round(t.protein/num(r.protein)*100,1)}% target`);if(r.calcium)a.push(`Calcium ${round(t.calcium/num(r.calcium)*100,1)}% target`);if(r.sodium)a.push(`Na ${round(t.sodium/num(r.sodium)*100,1)}% target`);if(r.potassium)a.push(`K ${round(t.potassium/num(r.potassium)*100,1)}% target`);if(w)a.push(`${round(t.kcal/w,1)} kcal/kg/day • ${round(t.protein/w,2)} g protein/kg/day`);return a.length?`<p class="muted top-gap"><strong>Requirement comparison:</strong> ${a.join(' • ')}</p>`:''}$('calculateBtn').addEventListener('click',()=>{calculateIntake();renderSummary()});
