function renderFoodDB(){ensureFoodDbDraft();const body=$('foodDbBody');body.innerHTML='';const typ=$('dbTypeFilter').value||'all',q=($('dbSearch').value||'').toLowerCase();const clinicalTypeOrder={food:0,formula:1,modular:2,medication:3};
const clinicalSubgroup=f=>{const n=String(f.name||'').toLowerCase(),ps=String(f.protein_source||'');if(f.type==='food'){if(ps==='cho_source'||/ข้าว|โจ๊ก|ข้าวต้ม|เส้น|ขนมปัง|มัน|เผือก|แป้ง|starch|rice|bread|pasta/.test(n))return 0;if(ps==='meat'||/ไก่|หมู|ปลา|เนื้อ|ตับ|กุ้ง|เบคอน|meat|fish|chicken|pork/.test(n))return 1;if(ps==='egg'||/ไข่|egg/.test(n))return 2;if(/ผัก|vegetable|broccoli|carrot/.test(n))return 3;if(/ผลไม้|กล้วย|แอป|ส้ม|มะละกอ|แตง|องุ่น|เงาะ|ฝรั่ง|มะม่วง|fruit|apple|banana|orange/.test(n))return 4;if(/น้ำมัน|เนย|กะทิ|น้ำสลัด|oil|butter|fat/.test(n))return 5;return 6}if(f.type==='formula'){if(String(f.basis_unit||'').toLowerCase()==='ml')return 0;if(/infant|สูตร 1|สูตร1|preterm|neonate/.test(n))return 1;if(/lf|pepti|neocate|nutramigen|infratini|gastro|special/.test(n))return 2;return 3}if(f.type==='modular'){if(ps==='meat'||/protein|whey/.test(n))return 0;if(/dextrin|carbo|cho/.test(n))return 1;if(/mct/.test(n))return 3;if(/oil|น้ำมัน|fat/.test(n))return 2;return 4}if(f.type==='medication'){if(/nacl|sodium|โซเดียม/.test(n))return 0;if(/kcl|potassium|โพแทสเซียม/.test(n))return 1;if(/caco3|calcium|แคลเซียม/.test(n))return 2;if(/magnesium|แมกนีเซียม/.test(n))return 3;if(/phosph|ฟอส/.test(n))return 4;return 5}return 9};
const rows=foodDbDraft.filter(f=>(typ==='all'||f.type===typ)&&(!q||String(f.name||'').toLowerCase().includes(q))).sort((a,b)=>(b._new?1:0)-(a._new?1:0)||(clinicalTypeOrder[a.type]??9)-(clinicalTypeOrder[b.type]??9)||clinicalSubgroup(a)-clinicalSubgroup(b)||String(a.name||'').localeCompare(String(b.name||''),'th',{sensitivity:'base'}));rows.forEach(f=>{const tr=document.createElement('tr');tr.innerHTML=`<td><select data-k="type"><option value="food">Food</option><option value="formula">Formula</option><option value="modular">Modular</option><option value="medication">Medication / mineral</option></select></td><td class="db-name"><input data-k="name" value="${esc(f.name)}"><div class="db-row-actions"><button class="small-btn secondary conversion-toggle">Conversions (${savedConversions(f).length})</button><button class="small-btn danger delete-row">Delete</button>${f._dirty?'<span class="dirty-pill">Edited</span>':''}</div></td><td><input data-k="basis_value" type="number" step="0.01" value="${esc(f.basis_value)}" style="width:70px"><select data-k="basis_unit">${["g","mL","portion","เม็ด","ซอง","ขวด","ampule","ทัพพี","ถ้วยตวง","ช้อนโต๊ะ","ช้อนชา","ฟอง","ฝัก","หัวเล็ก","ผลกลาง","ผลเล็ก","ผลใหญ่","กลีบใหญ่","เม็ดกลาง","ชิ้นขนาดคำ","จับใหญ่","ห่อ","แผ่น","แผ่นเล็ก","แผ่นใหญ่"].map(u=>`<option>${u}</option>`).join("")}</select></td><td><input data-k="grams_per_scoop" type="number" step="0.01" value="${esc(f.grams_per_scoop||'')}"></td><td><input data-k="standard_kcal_oz" type="number" step="0.1" value="${esc(f.standard_kcal_oz||'')}" placeholder="formula only"></td><td><input data-k="min_kcal_oz" type="number" step="0.1" value="${esc(f.min_kcal_oz||'')}" placeholder="formula only"></td><td><input data-k="max_kcal_oz" type="number" step="0.1" value="${esc(f.max_kcal_oz||'')}" placeholder="formula only"></td><td><select data-k="protein_source">${PROTEIN_SOURCE_OPTIONS.map(([v,l])=>`<option value="${v}" ${f.protein_source===v?'selected':''}>${l}</option>`).join('')}</select></td>${['kcal','protein','fat','mct','cho','calcium','magnesium','phosphorus','sodium','potassium','iron','zinc'].map(k=>`<td><input data-k="${k}" type="number" step="0.01" value="${esc(f[k]??'')}"></td>`).join('')}<td><input data-k="source" value="${esc(f.source||'Custom')}"></td>`;tr.querySelector('[data-k="type"]').value=f.type;tr.querySelector('[data-k="basis_unit"]').value=f.basis_unit;tr.querySelectorAll('[data-k]').forEach(el=>{const fn=()=>{f[el.dataset.k]=el.value;if(el.dataset.k==='protein_source')f.protein_source_user_set=true;markFoodDbDirty(f)};el.addEventListener('input',fn);el.addEventListener('change',fn)});tr.querySelector('.conversion-toggle').onclick=()=>{openConversionRows.has(f.id)?openConversionRows.delete(f.id):openConversionRows.add(f.id);renderFoodDB()};tr.querySelector('.delete-row').onclick=()=>{if(confirm(`Mark “${f.name||'this item'}” for deletion? It will be deleted when you press Save Custom Database.`)){foodDbDraft=foodDbDraft.filter(x=>x.id!==f.id);markFoodDbDirty();openConversionRows.delete(f.id);renderFoodDB()}};body.appendChild(tr);if(openConversionRows.has(f.id))body.appendChild(conversionEditorRow(f,21))});if($('foodDbSaveStatus')&&!foodDbDirty)$('foodDbSaveStatus').innerHTML='<span class="saved-pill">Saved</span>'}
