function candidateOptions(selectedId='',filterFn=null){const arr=(state.foodDB||[]).filter(f=>!filterFn||filterFn(f));return `<option value="">— choose from Custom DB —</option>${arr.map(f=>`<option value="${f.id}" ${selectedId===f.id?'selected':''}>[${esc(f.type)}] ${esc(f.name)}</option>`).join('')}`}
