function defaultRoundRule(row,kind='diet'){if(row?.roundRule)return String(row.roundRule);const f=state.foodDB.find(x=>x.id===row?.dbMatchId),u=String(row?.unit||f?.basis_unit||'').toLowerCase(),n=String(row?.name||f?.name||'').toLowerCase();if(kind==='fortifier'||kind==='modular')return '1';if(kind==='formula')return (u==='g'||String(f?.basis_unit||'').toLowerCase()==='g')?'1':'5';if(kind==='diet'){if(row?.group==='oil'||/น้ำมัน|\boil\b/.test(n))return '1';return ['g','ml'].includes(u)?'5':'1'}return '1'}
