function dbPick(names=[],filterFn=null){
  const db=(state.foodDB||[]).filter(f=>!filterFn||filterFn(f));
  for(const n of names){const q=String(n).trim().toLowerCase();const ex=db.find(f=>String(f.name||'').trim().toLowerCase()===q);if(ex)return ex}
  for(const n of names){const q=String(n).trim().toLowerCase();const pa=db.find(f=>String(f.name||'').trim().toLowerCase().includes(q));if(pa)return pa}
  return db[0]||null;
}
function preferredDietUnit(group,f){if(!f)return '';const avail=new Set([f.basis_unit,...savedConversions(f).map(c=>c.unit),...(f.portions||[]).map(c=>c.unit)].filter(Boolean));const choose=(arr)=>arr.find(u=>avail.has(u))||'';if(group==='starch')return choose(['ทัพพี'])||f.basis_unit||'g';if(group==='meat')return choose(['ช้อนโต๊ะ'])||f.basis_unit||'g';if(group==='egg')return choose(['ฟอง'])||f.basis_unit||'g';if(group==='vegetable')return choose(['ทัพพี'])||f.basis_unit||'g';if(group==='fruit')return choose(['ผล','ลูก','ผลกลาง','ผลเล็ก','ผลใหญ่'])||f.basis_unit||'g';if(group==='oil')return choose(['mL'])||f.basis_unit||'g';return f.basis_unit||'g'}
