  rows.forEach(r=>{if(!rowIsConstrained(r))r.amount=Math.max(0,num(r.amount))});
  let actual=dietDesignCalc(d).total.kcal;
  if(actual>targetKcal&&actual>0){const f=targetKcal/actual;rows.forEach(r=>{if(!rowIsConstrained(r))r.amount=Math.max(0,num(r.amount)*f)});actual=dietDesignCalc(d).total.kcal;return {target:targetKcal,actual,limited:false}}
