    const ageM=ageMonthsNow();
    let f=ageM>=12?dbPick(['นมสดธรรมดา','นมจืดโฟโมสต์'],x=>(x.type==='formula'||x.protein_source==='milk')):dbPick(['breast milk'],x=>x.type==='formula');
